window.__T__=[{"i":7520,"text":"一张动漫风格的 YouTube 直播封面，主角是一位活泼的女性 VTuber。她留着长长的 {argument name=\"hair color\" default=\"粉色配浅蓝色挑染\"} 头发，有着蓝色双眸，佩戴着带有麦克风的黑白猫耳耳机。她身穿白色翻领衬衫，系着黑粉色星形丝带，戴着黑色颈圈，手托下巴微笑着。背景是一个游戏房间，采用 {argument name=\"room lighting\" default=\"紫蓝色霓虹\"} 灯光，桌上摆放着 1 个白色键盘、1 个马克杯、1 个发光的猫咪摆件、1 个游戏手柄和 1 个直播麦克风。左侧是醒目且充满波普艺术风格的日文排版：上方是亮粉色的单词“{argument name=\"main text line 1\" default=\"雑談\"}”，下方是亮蓝色的单词“{argument name=\"main text line 2\" default=\"配信\"}”。下方有一条粉色横幅，写着“{argument name=\"subtitle text\" default=\"今夜もゆるっとトーク!\"}”。左上角有一个红色的“LIVE”徽章。画面中点缀着漂浮的对话气泡、星星和爱心。","imgs":["https://r2.qqsrc.com/images/originals/14230.jpg"]},{"i":7521,"text":"{\n  \"type\": \"动漫风格直播封面\",\n  \"character\": {\n    \"hair\": \"{argument name=\\\"hair color\\\" default=\\\"短银发配青色挑染\\\"}\",\n    \"eyes\": \"明亮的大蓝眼睛\",\n    \"outfit\": \"白色衬衫，黑色领带配银色装饰，黑色外套，黑色贝雷帽配大号蓝色心形宝石，蓝色宝石胸针，黑色颈圈\",\n    \"pose\": \"温柔微笑，注视观众，位于画面右侧\"\n  },\n  \"background\": \"马卡龙蓝色背景，带有白云、闪光、星星、小蝴蝶结以及精致的网格图案\",\n  \"typography_and_ui\": {\n    \"top_left_speech_bubble\": \"まったりおしゃべりしよ〜♡\",\n    \"main_title\": {\n      \"text\": \"{argument name=\\\"main title\\\" default=\\\"杂谈直播\\\"}\",\n      \"style\": \"大号字体，柔和蓝色渐变，白色描边，装饰有小爱心，位于画面中左侧\"\n    },\n    \"bottom_left_badges\": {\n      \"count\": 3,\n      \"style\": \"白色胶囊状按钮，左侧带有紫色爱心图标\",\n      \"labels\": [\n        \"{argument name=\\\"badge 1 text\\\" default=\\\"欢迎初见\\\"}\",\n        \"{argument name=\\\"badge 2 text\\\" default=\\\"积分收集\\\"}\",\n        \"{argument name=\\\"badge 3 text\\\" default=\\\"欢迎潜水\\\"}\"\n      ]\n    },\n    \"bottom_right_cloud_bubble\": \"気軽にコメントしてね♡\"\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14231.jpg"]},{"i":7522,"text":"{\n  \"type\": \"旅游广告横幅\",\n  \"background\": \"{argument name=\\\"destination scene\\\" default=\\\"地中海沿岸风光，拥有绿松石般的海水、悬崖边的村庄和蜿蜒的公路\\\"}，明媚晴天，右上角有太阳光晕，右下角有粉色三角梅\",\n  \"foreground\": \"{argument name=\\\"vehicle\\\" default=\\\"一辆复古浅蓝色汽车，后备箱上绑着一个棕色行李箱\\\"} 在沿海公路上行驶\",\n  \"layout\": {\n    \"typography\": [\n      { \"type\": \"main headline\", \"text\": \"{argument name=\\\"main headline\\\" default=\\\"开启一场说走就走的旅行。\\\"}\", \"style\": \"大号衬线字体，深蓝色到青色渐变，左对齐\" },\n      { \"type\": \"subheadline\", \"text\": \"{argument name=\\\"subheadline\\\" default=\\\"奔赴未见之景，开启下一个假期。\\\"}\", \"style\": \"中号衬线字体，深蓝色，两侧饰有装饰线条和星星\" },\n      { \"type\": \"accent text\", \"text\": \"出发，去探索世界。\", \"style\": \"手写风格，青色，配有虚线飞行轨迹和飞机图标\" }\n    ],\n    \"ui_elements\": [\n      { \"type\": \"badge\", \"position\": \"右上角\", \"shape\": \"圆形\", \"text\": \"让周末成为一生难忘的回忆\" },\n      { \"type\": \"cta button\", \"position\": \"左下角\", \"style\": \"药丸状，青色到绿色渐变\", \"text\": \"{argument name=\\\"cta text\\\" default=\\\"立即查看\\\"}\" }\n    ],\n    \"feature_bar\": {\n      \"position\": \"底部\",\n      \"count\": 3,\n      \"items\": [\n        { \"icon\": \"globe\", \"text\": \"众多绝美景点\" },\n        { \"icon\": \"camera\", \"text\": \"留下难忘体验\" },\n        { \"icon\": \"suitcase\", \"text\": \"周末即可出发\" }\n      ]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14232.jpg"]},{"i":7523,"text":"一张高度精细、写实风格的动漫肖像，描绘了一名年轻女性从低角度蹲下并微微俯视镜头的画面。她有着一头长长的、飘逸的 {argument name=\"hair color\" default=\"灰金色\"} 秀发，在微风中轻轻飘动，皮肤白皙，双眸大而富有表现力。她身穿 {argument name=\"outfit\" default=\"日本校服，搭配浅灰色开衫、白色衬衫、深色格纹领结、深色格纹百褶裙、深色过膝袜以及黑色皮质乐福鞋\"}。她的双臂随意地搭在膝盖上。背景是明亮的 {argument name=\"sky condition\" default=\"万里无云的蓝天，点缀着些许白云\"}，底部隐约可见模糊的 {argument name=\"background setting\" default=\"铁丝网围栏和绿树\"}，营造出校园的氛围。光线为明亮的自然日光，带有柔和的电影感阴影，突显了衣物和皮肤的写实质感。","imgs":["https://r2.qqsrc.com/images/originals/14233.jpg"]},{"i":7524,"text":"{\n  \"type\": \"旅游广告网页横幅\",\n  \"scene\": {\n    \"setting\": \"{argument name=\\\"destination type\\\" default=\\\"热带水上屋度假村\\\"}\",\n    \"background\": \"绿松石色的海水、蓝天、蓬松的云朵、棕榈树、远处的帆船、2 架带有虚线飞行路径的飞机\",\n    \"foreground_right\": \"木质甲板、2 把躺椅、白色坐垫、蓝色毛巾、草帽、圆桌、蓝色热带饮品、鸡蛋花、边缘处粉色木槿花装饰\"\n  },\n  \"layout\": {\n    \"text_overlay\": {\n      \"position\": \"左中\",\n      \"elements\": [\n        { \"type\": \"top_text\", \"text\": \"{argument name=\\\"top text\\\" default=\\\"开启下一段旅程。\\\"}\", \"decoration\": \"飞机图标、虚线\" },\n        { \"type\": \"main_headline\", \"text\": \"{argument name=\\\"main headline\\\" default=\\\"去邂逅这片美景。\\\"}\", \"style\": \"大型蓝色渐变衬线字体\" },\n        { \"type\": \"subheadline\", \"text\": \"{argument name=\\\"subheadline\\\" default=\\\"逃离日常，享受身心放松的假期。\\\"}\", \"decoration\": \"金色装饰漩涡纹样\" },\n        { \"type\": \"cta_button\", \"text\": \"{argument name=\\\"button text\\\" default=\\\"立即查看\\\"}\", \"style\": \"蓝青色渐变药丸形状，右箭头\" }\n      ]\n    },\n    \"bottom_features\": {\n      \"position\": \"左下\",\n      \"count\": 3,\n      \"items\": [\n        { \"icon\": \"棕榈树和海浪\", \"label\": \"绝美度假胜地\" },\n        { \"icon\": \"水上屋\", \"label\": \"非凡住宿体验\" },\n        { \"icon\": \"行李箱\", \"label\": \"适合周末出游\" }\n      ]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14234.jpg"]},{"i":7525,"text":"{\n  \"type\": \"日本超市促销传单\",\n  \"header\": {\n    \"store_name\": \"{argument name=\\\"store name\\\" default=\\\"ハピネス マーケット\\\"}\",\n    \"store_directory\": \"按地区分组的 12 家门店地址及电话号码列表\"\n  },\n  \"style\": \"高密度、色彩鲜艳、醒目的红黄价格标签、写实的食品摄影、传统的日本零售美学\",\n  \"layout\": {\n    \"sections\": [\n      {\n        \"title\": \"周二特价\",\n        \"position\": \"左上\",\n        \"count\": 3,\n        \"labels\": [\"稻荷寿司组合\", \"竹轮\", \"番茄\"]\n      },\n      {\n        \"title\": \"周三特价\",\n        \"position\": \"中上\",\n        \"promotion\": \"{argument name=\\\"point multiplier\\\" default=\\\"5倍\\\"}\",\n        \"count\": 6,\n        \"labels\": [\"酱油瓶\", \"日式甜点什锦包\", \"乌冬面\", \"猪肉片\", \"金枪鱼刺身块\", \"布丁\"]\n      },\n      {\n        \"title\": \"周四及周五特价\",\n        \"position\": \"右上\",\n        \"count\": 5,\n        \"labels\": [\"咖啡袋\", \"西兰花\", \"白萝卜\", \"猪肉片\", \"大号煎饺\"]\n      },\n      {\n        \"title\": \"中排折扣\",\n        \"position\": \"水平居中\",\n        \"count\": 7,\n        \"labels\": [\"苹果 9 折\", \"生菜\", \"酸奶\", \"寿司拼盘\", \"多连装酸奶\", \"冷冻食品 9 折\", \"大米 9 折\"]\n      },\n      {\n        \"title\": \"统一低价促销\",\n        \"position\": \"左下\",\n        \"price\": \"{argument name=\\\"low uniform price\\\" default=\\\"98\\\"}\",\n        \"count\": 6,\n        \"labels\": [\"什锦水果\", \"酸奶及乳制品\", \"纳豆和豆腐\", \"冰淇淋\", \"炸鸡\", \"三文鱼片\"]\n      },\n      {\n        \"title\": \"统一高价促销\",\n        \"position\": \"中下\",\n        \"price\": \"{argument name=\\\"high uniform price\\\" default=\\\"500\\\"}\",\n        \"count\": 4,\n        \"labels\": [\"五花肉片\", \"蜜柑和葡萄\", \"海鲜什锦\", \"烤鳗鱼\"]\n      },\n      {\n        \"title\": \"右侧栏促销\",\n        \"position\": \"右下\",\n        \"count\": 3,\n        \"labels\": [\"会员充值日\", \"积分卡活动\", \"炸制熟食\"]\n      }\n    ]\n  },\n  \"footer\": {\n    \"sale_period\": \"{argument name=\\\"sale period\\\" default=\\\"4/14(火) ▶ 17(金)\\\"}\",\n    \"disclaimers\": \"标准小字说明及辅助 Logo\"\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14235.jpg"]},{"i":7526,"text":"一张动漫风格的电影海报，前景是一位明亮、充满活力的女高中生，背景是一位安静的男高中生。女孩留着深紫色长发，装饰着丝带和音符发夹，身穿白色短袖校服衬衫、深色格纹裙和条纹领带。她温暖地微笑着，向前伸出手，递给观众一张纸，上面写着 {argument name=\"paper text\" default=\"この歌、あなたと、未来で届けたいです…♡\"}。背景中，男孩坐在书桌前，单手托腮，表情冷淡。他留着凌乱的深色头发，白色连帽衫外搭深色西装外套，脖子上挂着耳机。场景设定在一个阳光明媚的音乐制作室，配有显示音频波形的双电脑显示器、麦克风和键盘。画面呈现出明亮的电影级光效，带有镜头光晕和闪烁效果。醒目的文字叠加包括左侧巨大的粉色和蓝色垂直宣传语 {argument name=\"vertical text\" default=\"億再生 秘密 初恋 運命の歌\"}，底部中央巨大的风格化主标题 {argument name=\"main title\" default=\"放課後ミリオンノート\"}，并带有闪烁的渐变效果，下方是副标题 {argument name=\"subtitle\" default=\"〜陰キャの僕が億再生ボカロPだと、歌い手志望のお嬢様だけが知っている〜\"}。最底部是一块密集的电影演职员表，旁边是写有 {argument name=\"studio logo\" default=\"STELLA FILM THEATER\"} 的标志。","imgs":["https://r2.qqsrc.com/images/originals/14236.jpg"]},{"i":7527,"text":"{\n  \"type\": \"旅行广告网页横幅\",\n  \"background\": {\n    \"scene\": \"{argument name=\\\"destination scene\\\" default=\\\"风景如画的欧洲鹅卵石小镇广场，配有咖啡馆、喷泉和教堂塔楼\\\"}\",\n    \"lighting\": \"明媚晴天，温暖阳光\",\n    \"details\": \"咖啡馆桌椅，阳台上色彩鲜艳的花朵，远处的山脉，万里无云的湛蓝天空\",\n    \"props\": \"右侧建筑上挂着圆形的 'Caffè' 招牌，木制菜单板上列出 'Menu / Pasta / Insalata / Dolce / Vino'\"\n  },\n  \"overlay_elements\": {\n    \"graphics\": \"中左侧的邮戳，文字上方的虚线飞机航线，装饰性花纹\",\n    \"typography\": {\n      \"catchphrase\": {\n        \"text\": \"{argument name=\\\"catchphrase\\\" default=\\\"未知的街道，正在等待。\\\"}\",\n        \"style\": \"小型衬线字体，沿线条弯曲并配有飞机图标\"\n      },\n      \"main_headline\": {\n        \"text\": \"{argument name=\\\"main headline\\\" default=\\\"下个假期，去漫步街头。\\\"}\",\n        \"style\": \"大型优雅衬线字体，混合棕色、蓝色和粉色\"\n      },\n      \"subtitle\": {\n        \"text\": \"{argument name=\\\"subtitle\\\" default=\\\"漫步在石板路上，让心灵也变得轻盈。\\\"}\",\n        \"style\": \"中型衬线字体，两侧饰有复古装饰线条\"\n      }\n    },\n    \"call_to_action\": {\n      \"button_text\": \"{argument name=\\\"button text\\\" default=\\\"寻找旅行目的地 >\\\"}\",\n      \"style\": \"红色药丸状按钮，带有金色双线边框，居中置于文字下方\"\n    }\n  },\n  \"layout\": {\n    \"bottom_navigation_bar\": {\n      \"style\": \"顶部圆角的白色横幅\",\n      \"count\": 3,\n      \"items\": [\n        { \"icon\": \"camera\", \"label\": \"拍照打卡\" },\n        { \"icon\": \"fork and spoon\", \"label\": \"美食漫步\" },\n        { \"icon\": \"suitcase\", \"label\": \"轻松海外游\" }\n      ]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14237.jpg"]},{"i":7528,"text":"{\n  \"type\": \"VTuber 直播封面\",\n  \"theme\": \"粉嫩色系，柔和，可爱，蕾丝，丝带，爱心，兔子元素\",\n  \"character\": {\n    \"position\": \"右侧，半身像\",\n    \"appearance\": \"动漫少女，{argument name=\\\"hair color\\\" default=\\\"粉嫩色\\\"} 长卷发，大大的灰色眼睛，腮红，粉色爱心耳环\",\n    \"accessories\": \"白色兔耳朵，头上戴着大大的粉色蝴蝶结\",\n    \"outfit\": \"带有蕾丝的白色荷叶边连衣裙，领口处有带爱心宝石的大粉色蝴蝶结\"\n  },\n  \"layout\": {\n    \"background\": \"柔和的粉色，带有细微闪光、蕾丝图案和漂浮的爱心\",\n    \"text_elements\": [\n      {\n        \"type\": \"主标题\",\n        \"position\": \"左上角\",\n        \"style\": \"带有白色描边的大号艺术化粉色文字\",\n        \"text\": \"{argument name=\\\"main title\\\" default=\\\"雑談配信\\\"}\"\n      },\n      {\n        \"type\": \"对话气泡\",\n        \"position\": \"主标题上方\",\n        \"text\": \"まったり\"\n      },\n      {\n        \"type\": \"圆形徽章\",\n        \"position\": \"右上角\",\n        \"details\": \"蕾丝边缘，带有小粉色蝴蝶结\",\n        \"text\": \"きてくれてありがとう♡\"\n      },\n      {\n        \"type\": \"爱心徽章\",\n        \"position\": \"右下角\",\n        \"details\": \"大型蕾丝边缘爱心\",\n        \"text\": \"みんなとおしゃべりできるの楽しみにしてるね♡\"\n      }\n    ],\n    \"list_section\": {\n      \"position\": \"左下角\",\n      \"count\": 3,\n      \"style\": \"水平胶囊状横幅，带有蕾丝边缘，每个横幅左侧均有一个带有白色兔耳朵和微型蝴蝶结的粉色爱心\",\n      \"items\": [\n        \"{argument name=\\\"list item 1\\\" default=\\\"初見さん〇\\\"}\",\n        \"{argument name=\\\"list item 2\\\" default=\\\"ポイント回収〇\\\"}\",\n        \"{argument name=\\\"list item 3\\\" default=\\\"ROM〇\\\"}\"\n      ]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14238.jpg"]},{"i":7529,"text":"{\n  \"type\": \"2x3 美妆产品广告横幅网格\",\n  \"product\": \"{argument name=\\\"product name\\\" default=\\\"Glow Fit Cushion\\\"}\",\n  \"layout\": {\n    \"grid\": \"2 行 3 列\",\n    \"sections\": [\n      {\n        \"position\": \"左上\",\n        \"style\": \"柔粉色美妆人像\",\n        \"visuals\": \"皮肤透亮的年轻亚洲女性手持粉饼\",\n        \"title\": \"{argument name=\\\"main catchphrase\\\" default=\\\"素肌が、いちばんきれい。\\\"}\",\n        \"subtitle\": \"水润光泽气垫全新登场\",\n        \"badges\": [\"新品\"],\n        \"features_count\": 4,\n        \"feature_labels\": [\"水润感\", \"光泽感\", \"轻薄妆感\", \"持久持妆\"]\n      },\n      {\n        \"position\": \"中上\",\n        \"style\": \"自然米色极简风\",\n        \"visuals\": \"米色粉饼置于纹理石块上，伴有粉底涂抹痕迹\",\n        \"title\": \"自然体で、肌きれい。\",\n        \"subtitle\": \"还原素肌的自然遮瑕\",\n        \"badges\": [\"新品\"],\n        \"features_count\": 4,\n        \"feature_labels\": [\"自然遮瑕\", \"持久水润\", \"轻盈妆感\", \"不易脱妆\"]\n      },\n      {\n        \"position\": \"右上\",\n        \"style\": \"丁香色梦幻光泽\",\n        \"visuals\": \"紫色粉饼置于反光表面，带有心形光影反射\",\n        \"title\": \"光をまとって、透明感つづく。\",\n        \"subtitle\": \"#水光肌气垫\",\n        \"badges\": [\"新品\"],\n        \"features_count\": 3,\n        \"feature_labels\": [\"提亮肤色\", \"水润光泽肌\", \"{argument name=\\\"sun protection factor\\\" default=\\\"SPF50+ PA+++\\\"}\"]\n      },\n      {\n        \"position\": \"左下\",\n        \"style\": \"洁净白色现代风\",\n        \"visuals\": \"悬浮的粉色粉饼，伴有粉底涂抹痕迹\",\n        \"title\": \"MY BEST BASE\",\n        \"subtitle\": \"让你每天都想用的水润光泽气垫\",\n        \"hashtags\": [\"#自然遮瑕\", \"#持久水润\", \"#不易脱妆\"],\n        \"badges\": [\"新品\"],\n        \"features_count\": 4,\n        \"feature_labels\": [\"自然光泽\", \"轻盈贴合\", \"水润感\", \"持久持妆\"]\n      },\n      {\n        \"position\": \"中下\",\n        \"style\": \"亮粉色波普艺术\",\n        \"visuals\": \"亮粉色粉饼被闪光、星星和浮动文字气泡环绕\",\n        \"title\": \"{argument name=\\\"pop catchphrase\\\" default=\\\"盛れツヤ肌、つづく！\\\"}\",\n        \"subtitle\": \"#水润光泽气垫\",\n        \"badges\": [\"新品！\"],\n        \"features_count\": 4,\n        \"feature_labels\": [\"注入水润\", \"提升光泽\", \"{argument name=\\\"sun protection factor\\\" default=\\\"SPF50+ PA+++\\\"}\", \"不易脱妆\"],\n        \"bottom_banner\": \"可爱、轻松，每天都美丽。\"\n      },\n      {\n        \"position\": \"右下\",\n        \"style\": \"优雅金色奢华风\",\n        \"visuals\": \"金色粉饼置于垂坠丝绸面料上，点缀小白花\",\n        \"title\": \"{argument name=\\\"elegant catchphrase\\\" default=\\\"上質な素肌感を、ひと塗りで。\\\"}\",\n        \"subtitle\": \"专为成熟女性打造的光泽气垫\",\n        \"badges\": [\"新品\"],\n        \"features_count\": 4,\n        \"feature_labels\": [\"高级光泽\", \"高贴合遮瑕\", \"持久水润\", \"{argument name=\\\"sun protection factor\\\" default=\\\"SPF50+ PA+++\\\"}\"]\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14239.jpg"]},{"i":7530,"text":"一个逼真的 3D 平装书样机，以微倾斜角度直立在纯净的米白色背景上，展示了封面和书脊。封面采用极简且宁静的插画，描绘了一扇白色的拱门，门外是平静海面上明亮的柔和日出，一位身穿飘逸白裙的女性站在拱门处望向地平线。拱门左右两侧是优雅的竖排日文大字，采用明朝体（Mincho），内容为 {argument name=\"main title\" default=\"我慢をやめたら、人生が動き出した。\"}。左上角有较小的横排文字 {argument name=\"subtitle\" default=\"自分の人生を取り戻す 7つのステップ\"}。书的底部三分之一处包裹着淡粉色的腰封。腰封上印有醒目的横排宣传语 {argument name=\"obi catchphrase\" default=\"もう、他人軸で生きなくていい。\"}，上方通过虚线分隔的小字提到了工作、人际关系、爱情和未来焦虑。腰封右侧是一个带有小皇冠图标的白色圆形徽章，文字为 {argument name=\"sales badge text\" default=\"累計 20万部 突破!\"}。腰封最底部有 4 个小矩形框，包含关于自尊、时间管理、心理整理和理想未来的关键词，随后是文字 \"Everything will change!\"。书脊为白色，展示了主标题、副标题、作者名占位符以及出版社占位符。","imgs":["https://r2.qqsrc.com/images/originals/14240.jpg"]},{"i":7531,"text":"{\n  \"type\": \"时尚产品目录布局\",\n  \"theme\": \"一个具有特定图案的统一时尚系列：{argument name=\\\"pattern description\\\" default=\\\"紫色、绿色、蓝色、橙色和粉色的重叠圆形花卉曼陀罗图案\\\"}\",\n  \"layout\": {\n    \"structure\": \"2x2 网格布局，底部带有全宽横幅\",\n    \"sections\": [\n      {\n        \"id\": \"01\",\n        \"title\": \"{argument name=\\\"product 1\\\" default=\\\"喇叭裙\\\"}\",\n        \"subtitle\": \"フレアワンピース\",\n        \"main_image\": \"身穿图案喇叭裙并手提白色手袋的女性。\",\n        \"swatch_count\": 3,\n        \"swatch_descriptions\": [\"紫色款式\", \"绿/蓝色款式\", \"橙/黄色款式\"],\n        \"description_text\": \"华丽的喇叭廓形。轻盈的材质营造出优雅的动感。\"\n      },\n      {\n        \"id\": \"02\",\n        \"title\": \"{argument name=\\\"product 2\\\" default=\\\"丝巾\\\"}\",\n        \"subtitle\": \"シルクスカーフ\",\n        \"main_image\": \"身穿白色衬衫并佩戴图案丝巾的女性。\",\n        \"swatch_count\": 2,\n        \"swatch_descriptions\": [\"平铺图案细节\", \"系结细节\"],\n        \"description_text\": \"为颈部增添色彩的丝巾。具有上品的光泽感和顺滑的触感。\"\n      },\n      {\n        \"id\": \"03\",\n        \"title\": \"{argument name=\\\"product 3\\\" default=\\\"托特包\\\"}\",\n        \"subtitle\": \"トートバッグ\",\n        \"main_image\": \"背着图案托特包的女性。\",\n        \"swatch_count\": 3,\n        \"swatch_descriptions\": [\"紫色款式\", \"蓝色款式\", \"橙/黄色款式\"],\n        \"description_text\": \"可容纳 A4 尺寸的收纳空间。轻便耐用，是一款让人想每天使用的托特包。\"\n      },\n      {\n        \"id\": \"04\",\n        \"title\": \"{argument name=\\\"product 4\\\" default=\\\"收纳包\\\"}\",\n        \"subtitle\": \"ポーチ\",\n        \"main_image\": \"放在桌上，旁边有杂志和花瓶的图案拉链收纳包。\",\n        \"swatch_count\": 3,\n        \"swatch_descriptions\": [\"绿/紫色款式\", \"橙色款式\", \"粉色款式\"],\n        \"description_text\": \"点缀包内空间的华丽收纳包。细节之处尽显设计之美。\"\n      }\n    ],\n    \"bottom_banner\": {\n      \"title\": \"图案设计\",\n      \"description_text\": \"由细腻线条与丰富色彩交织而成的独一无二的图案设计。为日常生活增添一抹优雅色彩。\",\n      \"image\": \"展示无缝图案的水平长条图片。\"\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14241.jpg"]},{"i":7532,"text":"{\n  \"type\": \"VTuber 直播缩略图\",\n  \"style\": \"动漫风格，高细节，可爱，闪亮，以粉色为主色调\",\n  \"character\": {\n    \"description\": \"棕色双丸子头动漫少女，琥珀色眼睛，温柔微笑\",\n    \"outfit\": \"粉色和服搭配白色荷叶边女仆围裙，樱花发饰\",\n    \"pose\": \"手持装饰着花朵的粉色麦克风靠近脸颊\"\n  },\n  \"layout\": {\n    \"background\": \"带有闪光、发光爱心和装饰性粉色蝴蝶结的粉色渐变背景\",\n    \"text_sections\": [\n      {\n        \"type\": \"顶部丝带\",\n        \"text\": \"{argument name=\\\"top subtitle\\\" default=\\\"まったりおしゃべりしよ〜🤍\\\"}\"\n      },\n      {\n        \"type\": \"主标题\",\n        \"text\": \"{argument name=\\\"main title\\\" default=\\\"雑談配信\\\"}\",\n        \"decorations\": \"周围环绕 3 个大桃子插图\"\n      },\n      {\n        \"type\": \"中间丝带\",\n        \"text\": \"{argument name=\\\"middle subtitle\\\" default=\\\"みんなと楽しい時間を過ごしたいなっ♡\\\"}\"\n      },\n      {\n        \"type\": \"要点列表\",\n        \"position\": \"左下角\",\n        \"count\": 3,\n        \"icon\": \"桃子\",\n        \"labels\": [\n          \"{argument name=\\\"bullet 1\\\" default=\\\"初見さん〇\\\"}\",\n          \"{argument name=\\\"bullet 2\\\" default=\\\"ポイント回収〇\\\"}\",\n          \"ROMO\"\n        ]\n      },\n      {\n        \"type\": \"对话气泡\",\n        \"position\": \"右下角\",\n        \"text\": \"コメント大歓迎♪ いっぱいお話し しようねっ♡\"\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14242.jpg"]},{"i":7533,"text":"{\n  \"type\": \"推广图形网格\",\n  \"style\": \"极简主义，美学生活方式，女性化，{argument name=\\\"color palette\\\" default=\\\"柔米色、灰粉色和白色\\\"}\",\n  \"layout\": \"2 列 3 行网格，外加一个全宽页脚\",\n  \"panels\": [\n    {\n      \"position\": \"左上\",\n      \"text\": [\"AI 同步\", \"免费\", \"{argument name=\\\"main title\\\" default=\\\"AI 社区\\\"}\", \"学习、连接，在 AI 的助力下创造理想未来\"],\n      \"button\": \"加入社区 >\",\n      \"visuals\": \"笔记本电脑键盘、干花、柔和的拱形背景\"\n    },\n    {\n      \"position\": \"右上\",\n      \"text\": [\"AI 能做什么\", \"学习 AI，创造未来。\"],\n      \"list_items\": {\n        \"count\": 3,\n        \"items\": [\n          {\"icon\": \"lightbulb\", \"text\": \"业务提效，创造更多时间\"},\n          {\"icon\": \"pencil\", \"text\": \"创意赋能，将想法变为现实\"},\n          {\"icon\": \"person\", \"text\": \"个性化工作方式，实现理想未来\"}\n        ]\n      },\n      \"visuals\": \"咖啡杯、杂志、柔和阴影\"\n    },\n    {\n      \"position\": \"中左\",\n      \"text\": [\"{argument name=\\\"social platform 1\\\" default=\\\"X\\\"}\", \"发布最新资讯\", \"每日分享 AI 应用技巧与思维方式 ♡\", \"关注我！\"],\n      \"button\": \"查看 X >\",\n      \"visuals\": \"展示桌面场景的智能手机模型\"\n    },\n    {\n      \"position\": \"中右\",\n      \"text\": [\"{argument name=\\\"social platform 2\\\" default=\\\"Instagram\\\"}\", \"分享日常、学习与心得\", \"通过快拍分享真实生活 ♡\"],\n      \"button\": \"查看 Instagram >\",\n      \"visuals\": \"展示美学照片网格的智能手机模型\"\n    },\n    {\n      \"position\": \"左下\",\n      \"text\": [\"迈出第一步\", \"免费咨询\", \"欢迎随时分享你的想法或困惑\"],\n      \"button\": \"预约免费咨询 >\",\n      \"features\": {\n        \"count\": 3,\n        \"items\": [\n          {\"icon\": \"calendar\", \"text\": \"30 分钟在线咨询\"},\n          {\"icon\": \"laptop\", \"text\": \"绝无强制推销\"},\n          {\"icon\": \"heart\", \"text\": \"提供适合你的建议\"}\n        ]\n      },\n      \"visuals\": \"干花、柔和灯光\"\n    },\n    {\n      \"position\": \"右下\",\n      \"text\": [\"关于我\", \"以 AI 为伴，开启个性化工作方式\", \"支持女性职业发展与未来规划\"],\n      \"button\": \"查看详细个人资料 >\",\n      \"visuals\": \"扎着发髻的女性背影，身穿白衬衫，手持平板电脑\"\n    }\n  ],\n  \"footer\": {\n    \"text\": \"{argument name=\\\"footer text\\\" default=\\\"用 AI，创造属于我的未来。\\\"}\",\n    \"background\": \"灰粉色\"\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14243.jpg"]},{"i":7534,"text":"{\n  \"type\": \"推广 App 信息图传单\",\n  \"style\": \"可爱、柔和色调、亲和力强、扁平化矢量插图与柔和阴影结合、日式推广设计\",\n  \"header\": {\n    \"headline\": \"{argument name=\\\"main headline\\\" default=\\\"每天记录，轻松赚取积分！\\\"}\",\n    \"app_name\": \"{argument name=\\\"app name\\\" default=\\\"Unlog\\\"}\",\n    \"subtitle\": \"{argument name=\\\"app subtitle\\\" default=\\\"〜便便更健康，积分更快乐〜\\\"}\",\n    \"top_right_badge\": \"轻松养成健康习惯♪\",\n    \"main_illustration\": \"可爱的棕色便便表情符号角色坐在白色马桶上，手持智能手机并竖起大拇指\"\n  },\n  \"layout\": {\n    \"sections\": [\n      {\n        \"title\": \"什么是 Unlog？\",\n        \"position\": \"middle-left\",\n        \"type\": \"how_it_works\",\n        \"count\": 3,\n        \"steps\": [\n          {\"number\": 1, \"label\": \"排便后记录！\", \"icon\": \"马桶和智能手机\"},\n          {\"number\": 2, \"label\": \"获取积分！\", \"icon\": \"金色 P 硬币\"},\n          {\"number\": 3, \"label\": \"用积分兑换惊喜奖励！\", \"icon\": \"粉色礼盒\"}\n        ],\n        \"description\": \"每天的“便便记录”不仅能守护你的健康，还能让你获得实惠。\"\n      },\n      {\n        \"type\": \"app_ui_mockup\",\n        \"position\": \"middle-right\",\n        \"description\": \"智能手机显示日历，一个可爱的便便图标写着“今天也很顺畅！”，以及“+10P”\",\n        \"floating_badge\": \"每天记录 1 次，获取 10 积分！\"\n      },\n      {\n        \"title\": \"你可以积累的是……\",\n        \"position\": \"lower-middle-left\",\n        \"point_system\": \"{argument name=\\\"point name\\\" default=\\\"便便积分 (UP)!\\\"}\",\n        \"icon\": \"带有 UP 字样的便便形状\"\n      },\n      {\n        \"title\": \"UP 积分兑换奖励示例\",\n        \"position\": \"lower-middle-right\",\n        \"type\": \"rewards_list\",\n        \"count\": 4,\n        \"items\": [\n          {\"label\": \"咖啡券\", \"cost\": \"150UP~\", \"icon\": \"咖啡杯\"},\n          {\"label\": \"便利店甜点\", \"cost\": \"200UP~\", \"icon\": \"蛋糕\"},\n          {\"label\": \"Amazon 礼品卡 (500 日元)\", \"cost\": \"500UP~\", \"icon\": \"字母 a\"},\n          {\"label\": \"捐赠助力公益\", \"cost\": \"300UP~\", \"icon\": \"双手捧心\"}\n        ]\n      },\n      {\n        \"title\": \"还有贴心的辅助功能！\",\n        \"position\": \"bottom-above-footer\",\n        \"type\": \"features_list\",\n        \"count\": 4,\n        \"items\": [\n          {\"label\": \"通过排便记录管理体质\", \"icon\": \"剪贴板\"},\n          {\"label\": \"图表直观显示变化！\", \"icon\": \"柱状图\"},\n          {\"label\": \"提醒功能助力习惯养成\", \"icon\": \"铃铛\"},\n          {\"label\": \"隐私安全放心 (支持昵称)\", \"icon\": \"锁\"}\n        ]\n      }\n    ],\n    \"footer\": {\n      \"background_color\": \"teal\",\n      \"call_to_action\": \"{argument name=\\\"call to action\\\" default=\\\"立即免费下载！\\\"}\",\n      \"elements\": [\"App 图标\", \"App Store 徽章\", \"Google Play 徽章\", \"二维码\"]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14244.jpg"]},{"i":7535,"text":"{\n  \"type\": \"日式宣传海报\",\n  \"theme\": \"强烈的火焰能量、战斗精神、肌肉感、发光光环\",\n  \"color_palette\": [\"黑色\", \"烈焰橙\", \"红色\", \"金色\"],\n  \"layout\": {\n    \"header\": {\n      \"subtitle\": \"从全人类身上汲取极致的斗魂\",\n      \"main_title\": \"{argument name=\\\"main title\\\" default=\\\"究极斗魂海报\\\"}\"\n    },\n    \"center\": {\n      \"graphic\": \"带有火焰放射效果的边框发光海报\",\n      \"large_text\": \"{argument name=\\\"center kanji\\\" default=\\\"斗魂\\\"}\",\n      \"side_text\": [\"所有的灵魂，皆为战斗而生。\", \"抛弃迷茫。打破极限。燃烧灵魂。现在就变得更强，成就自我。\"]\n    },\n    \"left_column\": {\n      \"sales_badge\": {\n        \"text\": \"累计销量突破 {argument name=\\\"sales figure\\\" default=\\\"127,000\\\"} 张!!\",\n        \"subtext\": \"※截至 2024 年 5 月\"\n      },\n      \"feature_boxes\": {\n        \"count\": 3,\n        \"labels\": [\"注入斗魂\", \"气魄觉醒\", \"突破极限\"]\n      }\n    },\n    \"right_column\": {\n      \"character\": \"肌肉男向上呐喊，被火焰光环包围\",\n      \"shout_text\": \"燃烧灵魂吧！\",\n      \"testimonial_badge\": {\n        \"title\": \"全球强者认证\",\n        \"main\": \"压倒性效果!!\",\n        \"subtext\": \"工作、学习、训练，在任何场景下释放斗魂!!\"\n      }\n    },\n    \"lower_middle\": {\n      \"graphic\": \"一大群人向中央发光海报伸出双手的剪影\",\n      \"catchphrase\": \"{argument name=\\\"catchphrase\\\" default=\\\"这一张海报，将改变一切。斗魂永存。\\\"}\"\n    },\n    \"footer\": {\n      \"specs\": {\n        \"title\": \"压倒性的存在感\",\n        \"details\": [\"B2 尺寸 (728×515mm)\", \"超高精细印刷\"]\n      },\n      \"color_variations\": {\n        \"count\": 4,\n        \"labels\": [\"烈火之红\", \"觉醒之蓝\", \"不屈之黑\", \"黄金之辉\"]\n      },\n      \"bonuses\": {\n        \"count\": 3,\n        \"title\": \"限时优惠！附赠斗魂特典！\",\n        \"items\": [\"斗魂名言贴纸\", \"斗魂手机壁纸数据\", \"斗魂注入音源 (MP3)\"]\n      },\n      \"price_bar\": {\n        \"label\": \"灵魂价格\",\n        \"price\": \"{argument name=\\\"price\\\" default=\\\"¥2,980\\\"}\",\n        \"tax_shipping\": \"(含税) 免运费\",\n        \"cta\": \"别犹豫。现在，释放你的灵魂吧!!\"\n      }\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14245.jpg"]},{"i":7536,"text":"{\n  \"type\": \"双页漫画分镜\",\n  \"style\": \"高度精细的写实漫画风格，黑白，网点纸，戏剧性光影，心理惊悚\",\n  \"global_elements\": {\n    \"protagonist\": \"{argument name=\\\"main character description\\\" default=\\\"穿着西装的年轻日本上班族\\\"}\",\n    \"theme\": \"{argument name=\\\"core concept\\\" default=\\\"被一大群与自己一模一样的克隆人包围\\\"}\"\n  },\n  \"layout\": {\n    \"left_page\": {\n      \"type\": \"全页跨页大图\",\n      \"setting\": \"{argument name=\\\"setting\\\" default=\\\"夜晚的涩谷十字路口\\\"}\",\n      \"visuals\": \"主角独自站在十字路口中央，震惊地环顾四周，周围的人群全都是他自己的克隆人。\",\n      \"text_elements\": [\n        {\"type\": \"manga title logo\", \"text\": \"{argument name=\\\"manga title\\\" default=\\\"俺だらけの街\\\"}\"},\n        {\"type\": \"subtitle\", \"text\": \"第 1 话 交代\"},\n        {\"type\": \"narration box\", \"text\": \"那晚，世界悄然将我抛弃。\"},\n        {\"type\": \"sound effect\", \"text\": \"嘈杂……\"}\n      ]\n    },\n    \"right_page\": {\n      \"type\": \"5 分格垂直布局\",\n      \"panels\": [\n        {\n          \"panel_number\": 1,\n          \"visuals\": \"主角眼睛的特写，瞳孔因震惊而放大，满头大汗。\",\n          \"text_elements\": [\n            {\"type\": \"speech bubble\", \"text\": \"……哈？为什么……大家都是我？\"},\n            {\"type\": \"sound effect\", \"text\": \"咚\"}\n          ]\n        },\n        {\n          \"panel_number\": 2,\n          \"visuals\": \"一排 8 个穿着西装的克隆人面无表情地注视着前方。\",\n          \"text_elements\": [\n            {\"type\": \"sound effect\", \"text\": \"嘈杂……\"}\n          ]\n        },\n        {\n          \"panel_number\": 3,\n          \"visuals\": \"一个克隆人凑近震惊的主角耳边低语。\",\n          \"text_elements\": [\n            {\"type\": \"speech bubble\", \"text\": \"你的位置，已经有人顶替了。\"},\n            {\"type\": \"sound effect\", \"text\": \"嗖\"}\n          ]\n        },\n        {\n          \"panel_number\": 4,\n          \"visuals\": \"手中智能手机屏幕的特写，显示着一条推送通知。\",\n          \"text_elements\": [\n            {\"type\": \"screen text\", \"text\": \"开始交接。\"},\n            {\"type\": \"sound effect\", \"text\": \"叮\"}\n          ]\n        },\n        {\n          \"panel_number\": 5,\n          \"visuals\": \"城市街道上无尽克隆人群的远景。\",\n          \"text_elements\": [\n            {\"type\": \"narration box\", \"text\": \"最先消失的不是名字，也不是生命。而是容身之所。\"},\n            {\"type\": \"bottom left text\", \"text\": \"我，真的还有资格留在这里吗——？\"},\n            {\"type\": \"bottom right text\", \"text\": \"{argument name=\\\"cliffhanger text\\\" default=\\\"下期预告！\\\"}\"},\n            {\"type\": \"sound effect\", \"text\": \"嘈杂…… 嘈杂…… 嘈杂……\"}\n          ]\n        }\n      ]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14246.jpg"]},{"i":7537,"text":"一幅 {argument name=\"art style\" default=\"传统日本浮世绘木版画\"} 风格的风景画，画面中有一个 {argument name=\"main character\" default=\"拟人化的啤酒杯，有着泡沫丰富的杯顶、开心的笑脸、细长的黄色四肢以及传统凉鞋\"} 走在泥土小径上。角色手中拿着一把蓝色圆扇，上面写着汉字“{argument name=\"fan text\" default=\"凉\"}”。背景右侧有一棵大松树和一座木桥，桥上有 3 个小人正在穿过，另有 3 个小人走在小径上。左侧是高高的芦苇丛，边缘是一条通向远处 {argument name=\"background mountain\" default=\"白雪皑皑的富士山\"} 的河流，天空呈现出渐变色。左上角有一个传统的文字长方形边框，写着“{argument name=\"top left text\" default=\"东海道五十三次之内 由井\"}”，旁边有红色的艺术家印章，左下角也有一个相匹配的边框。图像具有复古、柔和的色调以及逼真的木版画纸张纹理。","imgs":["https://r2.qqsrc.com/images/originals/14247.jpg"]},{"i":7538,"text":"{\n  \"type\": \"烘焙食品宣传单\",\n  \"style\": \"温馨、舒适、自然，米色与柔和色调，带有撕纸元素和精致线条花卉插画的剪贴簿美学\",\n  \"brand\": {\n    \"name\": \"{argument name=\\\"brand name\\\" default=\\\"Hana to OYATSU\\\"}\",\n    \"social_handle\": \"@hana_to_oyatsu\"\n  },\n  \"layout\": {\n    \"top_section\": {\n      \"main_copy\": \"{argument name=\\\"main catchphrase\\\" default=\\\"ほっとひといき、私をやさしくしてくれるおやつ。\\\"}\",\n      \"sub_copy\": \"关于为放松时刻精心烘焙的甜点的段落\",\n      \"top_right_badge\": \"关于温和配料与日常幸福的圆形文字徽章\",\n      \"main_image\": \"装满玛德琳、费南雪和芝麻曲奇等各种烘焙食品的大号陶瓷盘，采用柔和的自然光拍摄，背景虚化，配有茶杯和绿植\"\n    },\n    \"middle_left_section\": {\n      \"ingredients_note\": {\n        \"background\": \"贴在背景上的撕纸碎片\",\n        \"title\": \"精心挑选的配料\",\n        \"count\": 4,\n        \"items\": [\"国产小麦粉\", \"发酵黄油\", \"蔗糖\", \"鸡蛋\"],\n        \"illustrations\": \"小麦秆和黄油块的小型线条插画\"\n      },\n      \"message_note\": {\n        \"background\": \"撕纸碎片\",\n        \"text\": \"关于犒劳自己或赠予挚爱的寄语\",\n        \"illustration\": \"手绘小爱心\"\n      }\n    },\n    \"middle_center_section\": {\n      \"section_title\": \"为您带来温和的甜味与治愈的口感\",\n      \"product_lineup\": {\n        \"count\": 3,\n        \"items\": [\n          {\n            \"name\": \"{argument name=\\\"product 1 name\\\" default=\\\"マドレーヌ\\\"}\",\n            \"image\": \"单个玛德琳\",\n            \"description\": \"外酥里嫩，散发黄油香气\"\n          },\n          {\n            \"name\": \"{argument name=\\\"product 2 name\\\" default=\\\"フィナンシェ\\\"}\",\n            \"image\": \"单个长方形费南雪\",\n            \"description\": \"浓郁杏仁风味，口感湿润\"\n          },\n          {\n            \"name\": \"{argument name=\\\"product 3 name\\\" default=\\\"ディアマンクッキー\\\"}\",\n            \"image\": \"两块圆形芝麻曲奇\",\n            \"description\": \"口感酥松，甜度适中，是搭配咖啡或茶的绝佳选择\"\n          }\n        ]\n      }\n    },\n    \"middle_right_section\": {\n      \"badge\": \"带有“手工烘焙甜点礼盒”文字和蝴蝶结插画的粉色圆形徽章\",\n      \"packaging_image\": \"系着丝带的牛皮纸礼盒，贴有白色标签，上面写着“For your cozy time Hana to OYATSU homemade baked sweets”，并配有植物线条插画\"\n    },\n    \"bottom_section\": {\n      \"feature_icons\": {\n        \"count\": 3,\n        \"items\": [\n          { \"icon\": \"礼盒\", \"text\": \"送礼首选\" },\n          { \"icon\": \"咖啡杯\", \"text\": \"搭配咖啡或茶享用\" },\n          { \"icon\": \"爱心\", \"text\": \"治愈温和的口感\" }\n        ]\n      },\n      \"footer\": {\n        \"banner_text\": \"愿这份幸福能传达给今天努力工作的你。\",\n        \"brand_info\": \"Hana to OYATSU 标志，副标题“用心制作的手工味道”\",\n        \"contact_info\": \"Instagram 标志、账号、标签以及二维码\"\n      }\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14248.jpg"]},{"i":7539,"text":"{ \"type\": \"活动海报\", \"theme\": \"日本夏季烟花大会\", \"visuals\": { \"background\": \"夜空中绽放着巨大而绚丽的金色、粉色、蓝色和紫色烟花\", \"midground\": \"河面映照着烟花倒影，远处可见山峦、拱桥以及沿岸闪烁的城市灯火\", \"foreground\": \"河岸草坪上坐着观赏的人群，部分人身着传统浴衣，右侧点缀着温暖的灯笼\" }, \"typography_and_layout\": { \"top_left\": { \"catchphrase\": \"{argument name=\\\"catchphrase\\\" default=\\\"夏夜，思念绽放。\\\"}\", \"title\": \"{argument name=\\\"festival name\\\" default=\\\"碧川市 清流烟花大会\\\"}\", \"subtitle\": \"—— 在碧蓝的流光中，盛开光之花 ——\" }, \"mid_left\": { \"date_time\": \"{argument name=\\\"event date\\\" default=\\\"2026 年 8 月 15 日\\\"} (周六) 19:30〜20:30 (暂定)\", \"venue\": \"会场：{argument name=\\\"venue\\\" default=\\\"碧川河畔 清流大桥周边\\\"}\" }, \"bottom_left_box\": { \"style\": \"复古装饰边框\", \"content\": \"{argument name=\\\"highlights\\\" default=\\\"约 10,000 发与音乐同步的华丽烟花\\\"} 尺玉・星光烟花 水中烟花等\" }, \"footer\": { \"style\": \"底部深蓝色横幅\", \"section_count\": 3, \"sections\": [ { \"icon\": \"train\", \"title\": \"交通指南\", \"details\": \"步行距离及接驳巴士信息\" }, { \"icon\": \"paper lantern\", \"title\": \"观赏须知\", \"details\": \"关于垃圾处理、座位安排及禁止使用无人机的 3 点说明\" }, { \"element\": \"QR code\", \"text\": \"请通过官网查看最新信息\" } ], \"bottom_edge\": \"主办方及联系方式（含占位电话号码）\" } } }","imgs":["https://r2.qqsrc.com/images/originals/14249.jpg"]},{"i":7540,"text":"{\n  \"type\": \"manga page\",\n  \"style\": \"anime illustration, full color\",\n  \"characters\": {\n    \"woman\": {\n      \"appearance\": \"长 {argument name=\\\"hair color\\\" default=\\\"黑色\\\"} 头发，紫色眼睛\",\n      \"outfit\": \"{argument name=\\\"shirt color\\\" default=\\\"灰色\\\"} 长袖衬衫，深灰色紧身牛仔裤，赤脚\"\n    },\n    \"delivery_man\": {\n      \"appearance\": \"秃头，年长男性，浓眉\",\n      \"outfit\": \"蓝色工作夹克，内搭灰色衬衫\"\n    }\n  },\n  \"layout\": {\n    \"description\": \"页面垂直分割。左侧包含 4 个堆叠的横向分镜。右侧是一个高大的纵向分镜。\",\n    \"left_column_panels\": [\n      {\n        \"panel_number\": 1,\n        \"scene\": \"女性坐在客厅的灰色沙发上，手里拿着一个白色马克杯。\",\n        \"text_elements\": [\n          { \"type\": \"speech_bubble\", \"text\": \"？\" },\n          { \"type\": \"sound_effect\", \"text\": \"叮咚♪\", \"description\": \"门铃声\" }\n        ]\n      },\n      {\n        \"panel_number\": 2,\n        \"scene\": \"女性打开前门。快递员站在门外，手里拿着一个纸箱，面带微笑。\",\n        \"text_elements\": [\n          { \"type\": \"speech_bubble\", \"speaker\": \"delivery_man\", \"text\": \"{argument name=\\\"delivery greeting\\\" default=\\\"您好〜！快递来啦！\\\"}\" },\n          { \"type\": \"speech_bubble\", \"speaker\": \"woman\", \"text\": \"啊，好的……谢谢\" }\n        ]\n      },\n      {\n        \"panel_number\": 3,\n        \"scene\": \"快递员热情大笑的特写，背景是闪闪发光的粉色。\",\n        \"text_elements\": [\n          { \"type\": \"speech_bubble\", \"speaker\": \"delivery_man\", \"text\": \"{argument name=\\\"creepy compliment\\\" default=\\\"哎呀〜？哎呀呀，真是位大美人啊！像您这么漂亮的人独自居住，真是太可惜了呢〜♪\\\"}\" }\n        ]\n      },\n      {\n        \"panel_number\": 4,\n        \"scene\": \"女性感到厌恶和不适的特写，微微冒汗。前景可见快递员的后脑勺。\",\n        \"text_elements\": [\n          { \"type\": \"speech_bubble\", \"speaker\": \"delivery_man\", \"text\": \"话说回来，您的皮肤真好！身材也超棒的〜简直像模特一样！\" },\n          { \"type\": \"thought_bubble\", \"speaker\": \"woman\", \"text\": \"{argument name=\\\"woman reaction\\\" default=\\\"诶……？这人是谁啊……感觉有点恶心……\\\"}\" },\n          { \"type\": \"caption_box\", \"text\": \"此后，快递员依然在喋喋不休地夸赞着……\" }\n        ]\n      }\n    ],\n    \"right_column_panel\": {\n      \"panel_number\": 5,\n      \"scene\": \"女性全身肖像，站在室内，双臂交叉，神情恼怒且充满怀疑。\",\n      \"text_elements\": [\n        { \"type\": \"thought_bubble\", \"speaker\": \"woman\", \"text\": \"到底是谁啊……？\" }\n      ]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14250.jpg"]},{"i":7541,"text":"{\n  \"type\": \"宣传横幅广告\",\n  \"style\": \"充满活力、高能量、动漫风格，漫画书式的爆发背景，配有黄色星星和动作线条\",\n  \"product\": {\n    \"description\": \"一副 {argument name=\\\"product color\\\" default=\\\"亮黑色\\\"} 夹耳式无线耳机\",\n    \"position\": \"中左\"\n  },\n  \"character\": {\n    \"description\": \"棕色头发、绿色眼睛的 Q 版动漫男孩，身穿 {argument name=\\\"character outfit\\\" default=\\\"绿色和服\\\"}，戴着粉色花朵发夹，指向中心文字\",\n    \"position\": \"中右\"\n  },\n  \"layout\": {\n    \"top_left_ribbon\": \"新品上市！\",\n    \"center_text_stack\": {\n      \"line_1\": \"轻轻一夹！\",\n      \"line_2\": \"{argument name=\\\"main catchphrase\\\" default=\\\"新感官耳机！\\\"}\",\n      \"tags\": {\n        \"count\": 3,\n        \"labels\": [\"轻盈\", \"舒适\", \"不入耳！\"]\n      },\n      \"ribbon\": \"长时间佩戴也轻松自如！\",\n      \"product_logo\": \"{argument name=\\\"product name\\\" default=\\\"EarFun Clip\\\"}\"\n    },\n    \"bottom_right_burst\": {\n      \"text\": \"限时优惠！亚马逊现已 {argument name=\\\"discount text\\\" default=\\\"8.7 折！\\\"}\"\n    },\n    \"bottom_left_features\": {\n      \"count\": 4,\n      \"shape\": \"蓝色六边形图标\",\n      \"labels\": [\"轻轻一夹\", \"轻量化设计\", \"超长续航\", \"高音质清晰音效\"]\n    },\n    \"bottom_banner\": \"立即前往亚马逊查看！\"\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14251.jpg"]},{"i":7542,"text":"{\n  \"type\": \"轻小说封面插画\",\n  \"style\": \"动漫艺术风格，高度细节化，戏剧性光影，碎玻璃元素\",\n  \"typography\": {\n    \"title\": \"{argument name=\\\"main title\\\" default=\\\"普通しか取り柄のない私と、街角で出会った“音に狂う少女” 私の声で覚醒する天才たちが世界を震わせる、名もない物語\\\"}\",\n    \"subtitle\": \"{argument name=\\\"catchphrase\\\" default=\\\"——歌った瞬間だけ、“私”になる。\\\"}\",\n    \"credits\": [\n      \"著者：{argument name=\\\"author name\\\" default=\\\"雾岛 澄音\\\"}\",\n      \"イラスト：{argument name=\\\"illustrator name\\\" default=\\\"天濑 里奥\\\"}\",\n      \"{argument name=\\\"label name\\\" default=\\\"Aurora Note\\\"}\"\n    ]\n  },\n  \"layout\": {\n    \"description\": \"对角线动态分镜，分隔 5 个不同的角色场景\",\n    \"panels\": [\n      {\n        \"position\": \"左半部分\",\n        \"character\": \"普通高中女生，棕色波波头，白色海军风制服\",\n        \"action\": \"敬畏地抬头仰望，微微伸手\",\n        \"background\": \"白天的城市街道，明亮的阳光\"\n      },\n      {\n        \"position\": \"右上角\",\n        \"character\": \"摇滚少女，银色长发，黑色哥特装，颈圈\",\n        \"action\": \"弹奏着发光的蓝色电吉他\",\n        \"background\": \"夜晚的舞台，破碎的蓝色水晶特效\"\n      },\n      {\n        \"position\": \"中右侧\",\n        \"character\": \"贝斯手少女，蓝色长发，休闲 T 恤和短裤\",\n        \"action\": \"躺着弹奏贝斯\",\n        \"background\": \"凌乱的房间，音乐设备，效果器踏板，能量饮料罐\"\n      },\n      {\n        \"position\": \"左下角\",\n        \"character\": \"键盘手少女，深色长发，女仆装\",\n        \"action\": \"坐在合成器键盘前，直播设置\",\n        \"background\": \"霓虹紫灯光房间，显示器，环形灯，麦克风\"\n      },\n      {\n        \"position\": \"右下角\",\n        \"character\": \"鼓手少女，黑色短发，黑色 T 恤，颈圈\",\n        \"action\": \"充满活力地演奏架子鼓\",\n        \"background\": \"昏暗的录音室\"\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14252.jpg"]},{"i":7543,"text":"{\n  \"type\": \"宣传海报\",\n  \"theme\": \"光芒四射、金色、闪耀、极致的幸福\",\n  \"color_palette\": [\"金色\", \"白色\", \"暖黄色\", \"粉色点缀\"],\n  \"header\": {\n    \"top_catchcopy\": \"汲取全人类极致幸福的情感精华\",\n    \"main_title\": \"{argument name=\\\"main title\\\" default=\\\"极致幸福\\\"}\",\n    \"subtitle\": \"{argument name=\\\"catchphrase\\\" default=\\\"即将传递给你！！\\\"}\",\n    \"title_style\": \"大号、粗体、闪耀的金色质感、3D 效果\"\n  },\n  \"hero_section\": {\n    \"image\": \"{argument name=\\\"hero subject\\\" default=\\\"一家三口开怀大笑，仰望天空，沐浴在金色的光芒中\\\"}\",\n    \"background\": \"彩虹、闪烁的粒子、发光的灵气\",\n    \"overlay_text_center\": \"这一张海报，将彻底改变你的人生！！\",\n    \"vertical_text_left\": \"幸福是可以传染的。你的笑容，将让世界变得幸福。\",\n    \"vertical_text_right\": \"为你带来史上最棒的幸福体验。\",\n    \"badge_top_right\": {\n      \"shape\": \"金色圆圈\",\n      \"text\": \"累计销量突破 {argument name=\\\"sales badge text\\\" default=\\\"300,000\\\"} 张！！\"\n    }\n  },\n  \"middle_section\": {\n    \"section_title\": \"实现极致幸福体验的 5 大幸福要点\",\n    \"count\": 5,\n    \"cards\": [\n      { \"number\": 1, \"title\": \"1 幸福觉醒\", \"image\": \"在日落海滩上举起双臂的人\" },\n      { \"number\": 2, \"title\": \"2 爱与感恩的连锁\", \"image\": \"四口之家温暖拥抱\" },\n      { \"number\": 3, \"title\": \"3 内心满足感 MAX\", \"image\": \"双手合十表达感恩的女性，散发着光芒\" },\n      { \"number\": 4, \"title\": \"4 转化为幸福体质\", \"image\": \"在花田中举起双臂的女性\" },\n      { \"number\": 5, \"title\": \"5 永恒的幸福循环\", \"image\": \"阳光明媚、繁花似锦的林间小径\" }\n    ]\n  },\n  \"bottom_section\": {\n    \"left_panel\": {\n      \"title\": \"限时优惠！附赠 5 大福利！！\",\n      \"list_count\": 5,\n      \"icon\": \"带有丝带的金色礼盒\"\n    },\n    \"center_panel\": {\n      \"title\": \"极致幸福海报\",\n      \"subtitle\": \"B2 尺寸 (728×515mm) 超高精细印刷 / 3 种设计可选\",\n      \"thumbnail_count\": 3,\n      \"thumbnail_labels\": [\"光之祝福版\", \"彩虹奇迹版\", \"花之喜悦版\"]\n    },\n    \"right_panel\": {\n      \"title\": \"灵魂定价\",\n      \"price\": \"{argument name=\\\"price\\\" default=\\\"¥2,980\\\"}\",\n      \"shipping\": \"免运费\",\n      \"style\": \"价格使用大号红色数字，金色背景\"\n    }\n  },\n  \"footer\": {\n    \"text\": \"幸福，越分享越充盈。来吧，将你的幸福传播到全世界！！\",\n    \"icon\": \"线条绘制的小红心\"\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14253.jpg"]},{"i":7544,"text":"这是一幅细节丰富、具有电影质感且超现实的插画，画面中一名身穿白色宇航服的宇航员正跪着小心翼翼地修剪一棵 {argument name=\"plant type\" default=\"盆景树\"}。宇航员位于一块漂浮的 {argument name=\"architecture style\" default=\"破败的古典大理石神庙\"} 碎片上，遗迹上爬满了常春藤和苔藓，装饰着华丽的金边、古典立柱以及一座女性石像。该平台悬浮在太空的零重力环境中。漂浮的碎片，包括岩石、大理石块和散落的叶子，在场景周围失重地飘动。背景中，一颗 {argument name=\"background planet\" default=\"巨大的红橙色行星\"} 占据了星光璀璨的宇宙。光影效果戏剧化且逼真，突显了古代遗迹、精致自然与未来感宇航员之间的对比。","imgs":["https://r2.qqsrc.com/images/originals/14254.jpg"]},{"i":7545,"text":"{\n  \"type\": \"等轴测 3D 地图插画\",\n  \"style\": \"复古地图绘制风格，融合高度精细的微缩模型，暖色调灯光，移轴摄影效果\",\n  \"background\": \"带有淡淡等高线和地图网格的陈旧羊皮纸\",\n  \"title_section\": {\n    \"position\": \"左上角\",\n    \"main_text\": \"{argument name=\\\"city name\\\" default=\\\"汕头\\\"}\",\n    \"subtitle_english\": \"{argument name=\\\"english city name\\\" default=\\\"SHANTOU\\\"}\",\n    \"subtitle_chinese\": \"海滨邹鲁 · 鮀城通商\",\n    \"seal\": \"红色方形印章\"\n  },\n  \"map_elements\": {\n    \"terrain\": \"沿海城市半岛，四周环绕蓝色水域，点缀着小船、礁石海岸和秋色树木\",\n    \"architecture\": \"传统中式亭台、欧式历史建筑与现代摩天大楼的密集融合\",\n    \"infrastructure\": \"带有现代列车的高架铁路线、背景中的大型悬索桥以及蜿蜒的沿海公路\"\n  },\n  \"labels\": {\n    \"style\": \"带有黑色中文文本的竖直长方形木质标牌\",\n    \"count\": 9,\n    \"locations\": [\n      \"汕头小公园\",\n      \"中山公园\",\n      \"礐石大桥\",\n      \"汕头国际会展中心\",\n      \"镇邦美食街\",\n      \"南澳灯塔\",\n      \"汕头老城\",\n      \"西堤公园\",\n      \"妈屿岛风景区\"\n    ]\n  },\n  \"water_labels\": {\n    \"text\": \"南海\",\n    \"position\": \"中左侧水域\"\n  },\n  \"bottom_left_info\": {\n    \"title\": \"汕头地图\",\n    \"subtitle\": \"广东省汕头市\",\n    \"coordinates\": \"116°40'E 23°22'N\",\n    \"compass\": \"信息框上方水域中的经典罗盘玫瑰\"\n  },\n  \"bottom_right_poem\": {\n    \"text\": \"百载商埠通四海\\n潮汕文脉蕴千秋\\n海天胜迹多俊秀\\n岭东门户展宏图\",\n    \"seal\": \"红色方形印章\"\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14255.jpg"]},{"i":7546,"text":"一张电影质感的照片，画面中一位 {argument name=\"subject\" default=\"亚裔老妇人\"} 坐在光线昏暗的厨房里，正透过方形窗户凝视着 {argument name=\"time of day\" default=\"黄昏\"} 时分的 {argument name=\"window view\" default=\"平静的海面与远处的岛屿\"}。她以侧影示人，手中拿着 1 个透明玻璃杯。她坐在小桌旁，桌上放着 1 个银色保温瓶和 1 碗深色水果。桌边有 2 把木椅，一把由她坐着，另一把上搭着一块深色布料。室内处于深影之中，左侧台面上放着 1 个金属水壶，右侧墙上挂着 1 个圆形挂钟、1 个网兜，还有一个电灯开关。窗台上摆放着几枚小贝壳。整体氛围 {argument name=\"mood\" default=\"沉思而宁静\"}，窗外透进的柔和自然光映照着她的脸庞，与昏暗的室内形成对比。","imgs":["https://r2.qqsrc.com/images/originals/14257.jpg"]},{"i":7547,"text":"一张电影级摄影棚肖像，两位男士在深灰色纯色背景前面对面站立，气氛紧张。左侧是 {argument name=\"left actor\" default=\"Jensen Ackles\"}，身穿 {argument name=\"left costume\" default=\"深蓝色质感超级英雄战衣，配有红色手套、金色鹰形肩甲及斗篷\"}。右侧是 {argument name=\"right actor\" default=\"Antony Starr\"}，身穿 {argument name=\"right costume\" default=\"深绿色与黑色战术服，胸前带有星形徽章，配有红色手套\"}。右侧男士双手叉腰。戏剧性、情绪化的摄影棚灯光，高度细节，照片级真实感。","imgs":["https://r2.qqsrc.com/images/originals/14258.jpg"]},{"i":7548,"text":"{\"type\":\"日式宣传海报\",\"style\":\"极度张力、火热、暗黑写实、高对比度\",\"centerpiece\":\"特写：一名愤怒的亚洲男性在嘶吼，双眼红光闪烁，青筋暴起，紧握双拳，周身环绕火焰光环，伴有红色闪电\",\"layout\":{\"header\":{\"top_text\":\"{argument name=\\\"top headline\\\" default=\\\"全人类从极度愤怒中汲取的力量\\\"}\",\"main_title\":\"{argument name=\\\"main title\\\" default=\\\"终极激昂海报\\\"}\"},\"middle\":{\"left_vertical_text\":\"{argument name=\\\"vertical text\\\" default=\\\"不可原谅。\\\"}\",\"right_angled_text\":\"愤怒的顶点，释放吧！！\",\"sales_badge\":\"金色圆形徽章，标注 {argument name=\\\"sales figure\\\" default=\\\"135,000\\\"}\"},\"sections\":[{\"title\":\"features_grid\",\"count\":4,\"labels\":[\"愤怒觉醒\",\"压力粉碎\",\"极限突破\",\"完全燃烧\"]},{\"title\":\"bonus_box\",\"count\":1,\"labels\":[\"限时特惠！附赠愤怒爆发特典！\"]},{\"title\":\"price_and_variants\",\"count\":3,\"price\":\"{argument name=\\\"price\\\" default=\\\"¥2,980\\\"}\",\"labels\":[\"怒火红\",\"愤懑黑\",\"逆鳞金\"]}],\"footer\":\"黄色警示三角形，红色文字：注意 本海报将突破愤怒的临界点。\"}}","imgs":["https://r2.qqsrc.com/images/originals/14259.jpg"]},{"i":7549,"text":"一张极具电影感和氛围感的插画，描绘了一位留着黑色短发的年轻女性站在夜晚潮湿的城市街道上。她身穿深色夹克，目光看向一侧。在她上方，一条高架铁轨斜穿过街道，一列黄色列车正呼啸而过。城市中高楼林立，部分建筑上悬挂着带有日文字符的霓虹灯牌。街道被雨水打湿，倒映着城市和列车温暖而柔和的灯光。整体色调以深褐色、棕色和柔和的黄色为主，营造出一种忧郁、反乌托邦或赛博朋克的氛围。光线昏暗且弥散，呈现出大都市雨夜的典型景象。","imgs":["https://r2.qqsrc.com/images/originals/14260.jpg"]},{"i":7550,"text":"{\n  \"type\": \"技术概览信息图\",\n  \"style\": \"{argument name=\\\"visual style\\\" default=\\\"手绘技术草图，排版简洁\\\"}\",\n  \"product\": {\n    \"name\": \"{argument name=\\\"product name\\\" default=\\\"MACBOOK NEO\\\"}\",\n    \"subtitle\": \"14 英寸 {argument name=\\\"processor model\\\" default=\\\"M3 PRO\\\"} - 技术概览\"\n  },\n  \"layout\": {\n    \"centerpiece\": {\n      \"description\": \"打开的笔记本电脑等轴视图，展示了双风扇、铜质散热管、电池单元和逻辑项目等内部硬件组件\",\n      \"callouts_count\": 9,\n      \"callout_labels\": [\n        \"01 1080p 摄像头系统\",\n        \"02 显示屏组件\",\n        \"03 散热系统\",\n        \"04 传感器套件\",\n        \"05 连接项目\",\n        \"06 电池组\",\n        \"07 {argument name=\\\"main component\\\" default=\\\"APPLE M3 PRO 芯片\\\"}\",\n        \"08 Force Touch 触控板\",\n        \"09 扬声器系统\"\n      ]\n    },\n    \"sections\": [\n      {\n        \"title\": \"标题文本\",\n        \"position\": \"左上\",\n        \"content\": \"营销宣传语及 5 点规格列表\"\n      },\n      {\n        \"title\": \"图例\",\n        \"position\": \"中上\",\n        \"content\": \"4 个颜色编码箭头，指示 {argument name=\\\"accent colors\\\" default=\\\"红色、蓝色、橙色、绿色\\\"} 的电源、数据、热量和传感器流向线\"\n      },\n      {\n        \"title\": \"材质与数量\",\n        \"position\": \"右上\",\n        \"type\": \"表格\",\n        \"rows_count\": 7,\n        \"columns\": [\"#\", \"材质\", \"数量\", \"备注\"]\n      },\n      {\n        \"title\": \"尺寸与重量\",\n        \"position\": \"中右\",\n        \"content\": \"闭合状态下笔记本电脑的俯视图和侧视图，标注测量数据\"\n      },\n      {\n        \"title\": \"横截面（侧视图）\",\n        \"position\": \"左下（上半部分）\",\n        \"content\": \"侧面轮廓展示内部组件布局，带有 6 个标签\"\n      },\n      {\n        \"title\": \"后端 I/O（从左至右）\",\n        \"position\": \"左下（下半部分）\",\n        \"content\": \"侧面轮廓展示 6 个端口\"\n      },\n      {\n        \"title\": \"数据 / 电源流向图（俯视图）\",\n        \"position\": \"右下\",\n        \"content\": \"带有彩色流向线、图例和比例尺的线框俯视图\"\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14261.jpg"]},{"i":7551,"text":"一张高对比度的黑白插画，描绘了一位身穿笔挺西装的老年男子正在拔出武士刀。男子留着向后梳的白发，面部皱纹深刻，神情专注而凌厉，正低头注视着刀刃。他身穿深色西装，内搭白衬衫，系着深色领带。画面前景突出了他的双手，清晰可见的青筋和皱纹紧紧握住武士刀华丽的刀柄和刀鞘。背景为纯黑色，突出了戏剧性的光影效果，以及男子面部、双手和衣物上精细的交叉排线细节。整体风格类似于细节丰富、硬核的漫画或图像小说。","imgs":["https://r2.qqsrc.com/images/originals/14263.jpg"]},{"i":7552,"text":"一张 90 年代末的复古业余闪光灯照片，展示了一名年轻男子正在维修街机。他跪在深色花纹的街机厅地毯上，转头直视镜头，表情平和。他身穿深色短袖 T 恤、宽松的蓝色牛仔裤、厚底白色运动鞋，并戴着一顶深色棒球帽。街机的前下盖板敞开，露出了复杂的内部电子元件，包括杂乱的电线、绿色的电路板、大扬声器以及底部的金属散热风扇。机身侧面印有鲜艳的粉色、黑色和白色图形，上面写着“{argument name=\"arcade game title\" default=\"Dancing Stage\"}”字样以及品牌“{argument name=\"arcade brand\" default=\"KONAMI\"}”。场景设定在昏暗的街机厅内，背景中隐约可见其他发光的游戏机。一把螺丝刀放在他膝盖旁的地毯上。画面呈现出强烈的直射闪光灯效果、轻微的胶片颗粒感、深邃的阴影以及怀旧的 Y2K 美学风格。","imgs":["https://r2.qqsrc.com/images/originals/14264.jpg"]},{"i":7553,"text":"一张无人机航拍照片，展现了一片广袤且平坦的 {argument name=\"terrain color\" default=\"鲜绿色\"} 草原，向着遥远的地平线无限延伸。在画面近景下方，恰好有两只 {argument name=\"animal\" default=\"毛茸茸的白羊\"} 正在站立吃草。明亮清晰的日光将动物的影子投射在左侧，轮廓分明且深邃。地平线上方是 {argument name=\"sky condition\" default=\"晴朗的淡蓝色天空，点缀着几朵淡淡的薄云\"}。构图突出了景观的广阔空旷，以及与渺小动物之间的尺度对比。","imgs":["https://r2.qqsrc.com/images/originals/14265.jpg"]},{"i":7554,"text":"一张温馨办公室里进行心理咨询的幽默 3D 卡通插画。左侧，一位 {argument name=\"patient character\" default=\"失去果核、神情忧郁的拟人化牛油果半身\"} 坐在棕色皮质躺椅上，用细长的手臂比划着。上方的大对话气泡写着 \"{argument name=\"speech text\" default=\"我只是觉得内心空荡荡的\"}\"。右侧，心理咨询师是一位 {argument name=\"therapist character\" default=\"拟人化的银勺\"}，坐在绿色扶手椅上，手持一支黄色铅笔，在标有 \"NOTES\"（笔记）的记事本上书写。房间灯光温暖，木地板上铺着米色地毯，书架上放着纸巾盒和书籍，其中一本标题为 \"REFLECT LISTEN VALIDATE\"（反思、倾听、确认）。左侧墙上挂着一张海报，上面写着 \"{argument name=\"poster text\" default=\"接纳你的情绪没关系\"}\"，并配有一个小爱心。右侧墙上挂着一张文凭，上面写着 \"{argument name=\"diploma text\" default=\"SPOON UNIVERSITY SCHOOL OF LISTENING & VALIDATION\"}\"（勺子大学倾听与确认学院），并配有小勺子插图和金色印章。","imgs":["https://r2.qqsrc.com/images/originals/14268.jpg"]},{"i":7555,"text":"{\n  \"type\": \"日式宣传落地页海报\",\n  \"style\": \"超高能、爆炸式排版、色彩鲜艳、游乐园夜间庆典美学\",\n  \"layout\": {\n    \"top_section\": {\n      \"background\": \"夜空、烟花、摩天轮、过山车\",\n      \"subjects\": \"4 名年轻人欢呼、挥拳、动态光影\",\n      \"typography\": [\n        \"{argument name=\\\"main headline\\\" default=\\\"极致的快乐！！\\\"}\",\n        \"{argument name=\\\"sub headline\\\" default=\\\"太棒了！！希望能引起共鸣！！\\\"}\",\n        \"这一张海报，将彻底重塑你的精彩人生！！\"\n      ],\n      \"badges\": [\n        \"累计销量突破 {argument name=\\\"sales badge\\\" default=\\\"252,000\\\"} 张！！！\"\n      ]\n    },\n    \"middle_section\": {\n      \"title\": \"实现极致快乐体验的 5 大超爽看点\",\n      \"points_count\": 5,\n      \"points\": [\n        {\"number\": 1, \"label\": \"爆笑觉醒\", \"image\": \"人们大笑\"},\n        {\"number\": 2, \"label\": \"心跳 MAX\", \"image\": \"过山车轨道\"},\n        {\"number\": 3, \"label\": \"感动漩涡\", \"image\": \"烟花爆炸\"},\n        {\"number\": 4, \"label\": \"超解放区域\", \"image\": \"剪影在夕阳下跳跃\"},\n        {\"number\": 5, \"label\": \"无限循环\", \"image\": \"人群欢呼\"}\n      ]\n    },\n    \"bonus_section\": {\n      \"title\": \"限时特惠！附赠 5 大豪华特典！！！\",\n      \"items_count\": 5,\n      \"items\": [\n        \"① 限定设计海报\",\n        \"② 快乐名言手册 (PDF)\",\n        \"③ 超快乐播放列表 (MP3)\",\n        \"④ 手机壁纸套装\",\n        \"⑤ 快乐秘密影像\"\n      ]\n    },\n    \"bottom_section\": {\n      \"product_info\": {\n        \"name\": \"极致快乐海报\",\n        \"variants_count\": 3,\n        \"variants\": [\"全力全开版\", \"笑容爆发版\", \"感动巅峰版\"]\n      },\n      \"pricing\": {\n        \"label\": \"灵魂定价\",\n        \"amount\": \"{argument name=\\\"price\\\" default=\\\"¥2,980\\\"}\",\n        \"shipping\": \"包邮\"\n      }\n    },\n    \"footer\": {\n      \"text\": \"{argument name=\\\"footer call to action\\\" default=\\\"尽情享受极致人生！！现在就入手吧！！\\\"}\",\n      \"background_color\": \"洋红色\"\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14269.jpg"]},{"i":7556,"text":"{\n  \"type\": \"数字通讯页面布局\",\n  \"background\": \"放置在深色表面上的白色页面，带有发光的蓝色数字节点和连接线\",\n  \"header\": {\n    \"text\": \"{argument name=\\\"main headline\\\" default=\\\"AI 新闻 – 2026 年 4 月 20 日\\\"}\",\n    \"style\": \"深蓝色横幅上的白色文字，带有浅蓝色边框\"\n  },\n  \"layout\": {\n    \"sections\": [\n      {\n        \"id\": 1,\n        \"title\": \"{argument name=\\\"news item 1 title\\\" default=\\\"1. Anthropic Mythos 因网络能力引发全球警惕。\\\"}\",\n        \"image_description\": \"一条发光的蓝色网络巨龙从服务器中浮现，周围环绕着漂浮的数字挂锁。\",\n        \"layout_style\": \"图片在右侧，标题和文本在左侧，左下方配有青色引语。\"\n      },\n      {\n        \"id\": 2,\n        \"title\": \"{argument name=\\\"news item 2 title\\\" default=\\\"2. Claude Design 发布后，Adobe 和 Figma 股价下跌。\\\"}\",\n        \"image_description\": \"一张风格化的股票走势图，显示出参差不齐的红色下跌箭头和发光的蓝色上涨箭头，图中包含 Adobe、Figma 的标志以及一个 'AI' 图标。\",\n        \"layout_style\": \"图片在左侧，标题和文本在右侧。\"\n      },\n      {\n        \"id\": 3,\n        \"title\": \"{argument name=\\\"news item 3 title\\\" default=\\\"3. OpenAI 扩展 GPT-5.4-Cyber 和 Agents SDK。\\\"}\",\n        \"image_description\": \"一面发光的蓝色全息盾牌，中心带有 OpenAI 标志，周围环绕着数字链条和服务器背景。\",\n        \"layout_style\": \"标题和文本在左侧，图片在右侧。\"\n      },\n      {\n        \"id\": 4,\n        \"title\": \"4. NVIDIA 发布用于 3D 世界的 Lyra 2.0。\",\n        \"image_description\": \"一个充满活力、超现实的 3D 奇幻景观，拥有发光的植物、漂浮的岛屿，前景中有一个发光的蓝色相机图标。\",\n        \"layout_style\": \"图片在左侧，标题和文本在右侧。\"\n      },\n      {\n        \"id\": 5,\n        \"title\": \"5. OpenAI Image V2 提升产品摄影效果。\",\n        \"image_description\": \"一款豪华计时码表的对比图。左侧标有 'BEFORE'（较暗，细节较少），右侧标有 'AFTER (OpenAI Image V2)'（明亮，细节丰富，专业灯光）。\",\n        \"layout_style\": \"标题和文本在左侧，图片在右侧。\"\n      }\n    ],\n    \"count\": 5\n  },\n  \"footer\": {\n    \"text\": \"{argument name=\\\"footer hashtags\\\" default=\\\"#AI2025 #人工智能 #LLMs #AINews\\\"}\",\n    \"logo\": \"带有 '@oscarlau' 的 OL 标志\",\n    \"style\": \"底部深蓝色横幅上的白色文字\"\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14271.jpg"]},{"i":7557,"text":"{\n  \"type\": \"电子游戏截图样机\",\n  \"perspective\": \"第三人称越肩视角\",\n  \"character\": {\n    \"description\": \"从背后看到的男性主角\",\n    \"clothing\": \"灰色背心，印有“{argument name=\\\"shirt graphic\\\" default=\\\"LEONIDA MARINE CENTER\\\"}”图案，迷彩工装短裤\"\n  },\n  \"environment\": {\n    \"setting\": \"热带沿海小镇，土路，阳光明媚的白天，有零星云朵\",\n    \"left_side\": \"木制欢迎牌，写着“Welcome to {argument name=\\\"location name\\\" default=\\\"LEONIDA KEYS\\\"} YOUR PARADISE”，粉色塑料火烈鸟，热带植物，远处的水塔\",\n    \"center\": \"绿色建筑，带有“FISH”标志和马林鱼图案，招牌写着“BAIT TACKLE ICE BEER WINE”，行人走动\",\n    \"right_side\": \"两层木制建筑“Brian's Boat Works & Marina”，带有“Brian's Bar”霓虹灯招牌，停放的皮卡车，拖车上的摩托艇\"\n  },\n  \"ui_elements\": {\n    \"count\": 5,\n    \"components\": [\n      {\n        \"position\": \"左上角\",\n        \"type\": \"任务目标\",\n        \"text\": \"{argument name=\\\"mission title\\\" default=\\\"MEET RAUL\\\"}\\n{argument name=\\\"mission description\\\" default=\\\"Raul has some work for you at his boatyard\\\"}\"\n      },\n      {\n        \"position\": \"右上角\",\n        \"type\": \"状态 HUD\",\n        \"text\": \"13:47\\n$1,142\",\n        \"icon\": \"粉色棕榈树\"\n      },\n      {\n        \"position\": \"左下角\",\n        \"type\": \"小地图\",\n        \"description\": \"带有紫色边框的圆形地图，包含白色地图图标，其中“N”代表北方\"\n      },\n      {\n        \"position\": \"左下角，小地图右侧\",\n        \"type\": \"地点文字\",\n        \"text\": \"{argument name=\\\"location name\\\" default=\\\"LEONIDA KEYS\\\"}\\nPALM ISLAND\"\n      },\n      {\n        \"position\": \"右下角\",\n        \"type\": \"水印\",\n        \"text\": \"{argument name=\\\"game title\\\" default=\\\"GTA VI\\\"}\\nPRE-ALPHA FOOTAGE\"\n      }\n    ]\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14273.jpg"]},{"i":7558,"text":"{\n  \"type\": \"电商落地页首屏模型\",\n  \"aesthetic\": \"简洁、明亮、通透、柔美，带有紫色花卉装饰，{argument name=\\\"primary color\\\" default=\\\"柔粉色\\\"} 与白色调配色，柔和光影\",\n  \"header\": {\n    \"logo\": \"{argument name=\\\"brand name\\\" default=\\\"LUMEA BEAUTY\\\"}\",\n    \"navigation_links\": {\n      \"count\": 5,\n      \"labels\": [\"产品特色\", \"成分解析\", \"用户评价\", \"使用方法\", \"常见问题\"]\n    },\n    \"cta_button\": \"立即试用\"\n  },\n  \"hero_section\": {\n    \"left_column\": {\n      \"headline\": \"{argument name=\\\"headline text\\\" default=\\\"每一次照镜子，都能看见水润透亮。\\\"}\",\n      \"subheadline\": \"针对干燥与暗沉肌肤。蕴含奢华美容成分，为您打造日常集中保湿精华。\",\n      \"feature_badges\": {\n        \"count\": 3,\n        \"style\": \"药丸形状带小图标\",\n        \"labels\": [\"敏感肌适用\", \"深层保湿\", \"早晚可用\"]\n      },\n      \"bullet_points\": {\n        \"count\": 3,\n        \"style\": \"粉色勾选标记\",\n        \"labels\": [\"深入渗透美容成分\", \"重现紧致光泽感\", \"简单易坚持的护理\"]\n      },\n      \"cta_buttons\": {\n        \"count\": 2,\n        \"labels\": [\"首单优惠试用 >\", \"查看成分详情 >\"]\n      },\n      \"trust_badges\": \"包邮 / 首单优惠 / 无定期购买限制\"\n    },\n    \"center_subject\": {\n      \"model\": \"{argument name=\\\"model description\\\" default=\\\"年轻东亚女性，面带微笑，轻触脸颊\\\"}\",\n      \"action\": \"手持一瓶精华滴管\"\n    },\n    \"right_column\": {\n      \"product_display\": {\n        \"count\": 2,\n        \"items\": [\"{argument name=\\\"product type\\\" default=\\\"保湿精华\\\"} 滴管瓶\", \"产品包装盒\"]\n      },\n      \"stat_cards\": {\n        \"count\": 3,\n        \"style\": \"带有金色点缀的悬浮白色圆角矩形\",\n        \"labels\": [\"满意度 96%\", \"含 5 种美容成分\", \"用户突破 12,000 人\"]\n      }\n    }\n  },\n  \"bottom_section\": {\n    \"benefit_cards\": {\n      \"count\": 3,\n      \"style\": \"带有图标的水平白色圆角矩形\",\n      \"labels\": [\"水润感\", \"透亮感\", \"易用性\"]\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14274.jpg"]},{"i":7559,"text":"{\n  \"type\": \"移动端乙女游戏广告模型\",\n  \"characters\": {\n    \"male_target\": \"{argument name=\\\"男性角色描述\\\" default=\\\"帅气的年轻男子，留着凌乱的黑发，金色的眼睛，抽着烟，拿着智能手机\\\"}\",\n    \"female_player\": \"{argument name=\\\"女性角色描述\\\" default=\\\"可爱的动漫女孩，粉色双马尾，紫色眼睛，脸红，拿着智能手机\\\"}\"\n  },\n  \"layout\": {\n    \"top_section\": {\n      \"main_headline\": \"攻略那个危险的他！\",\n      \"sub_headline\": \"你会选哪一个？\",\n      \"game_logo\": \"{argument name=\\\"游戏标题\\\" default=\\\"Midnight Love Panic\\\"}\"\n    },\n    \"status_ui\": {\n      \"love_meter\": \"LOVE 99%，配有近乎全满的粉色进度条\",\n      \"male_level\": \"Lv.99，配有 6 颗心（5 颗红色实心，1 颗空心）\",\n      \"female_level\": \"Lv.1 熬夜党，配有 5 颗心（1 颗紫色实心，4 颗空心）\"\n    },\n    \"interaction_elements\": {\n      \"male_message_box\": \"{argument name=\\\"男性聊天消息\\\" default=\\\"今晚有空吗？能来我房间吗？😈\\\"}\",\n      \"female_thought_bubble\": \"诶，被叫去了……？如果去了会发生什么……？\",\n      \"warning_badge\": \"红色的锯齿状星形徽章，写着“99% 失败”，并带有汗滴\"\n    },\n    \"decision_section\": {\n      \"prompt_text\": \"能否抓住他的心，全看你的选择——\",\n      \"buttons\": [\n        { \"color\": \"green\", \"text\": \"{argument name=\\\"选项 1 文本\\\" default=\\\"去见他\\\"}\", \"indicator\": \"绿色向下箭头\" },\n        { \"color\": \"red\", \"text\": \"已读不回\", \"indicator\": \"红色向下箭头\" }\n      ]\n    },\n    \"bottom_section\": {\n      \"call_to_action\": \"立即游玩，配有天使翅膀\",\n      \"sub_text\": \"点击即可改变命运……\",\n      \"currency_display\": \"9,999 +，配有紫色钻石图标\"\n    }\n  }\n}","imgs":["https://r2.qqsrc.com/images/originals/14275.jpg"]}];